// Gerado por scripts/capturar-legado.mjs a partir de acesso/sumario_executivo_cheias/sumario_executivo_ribeira_iguape.html — não edite à mão.
export default "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n\n<title>Sumário Executivo - Vale do Ribeira de Iguape</title>\n\n<link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\n\n<style>\n\n:root {\n    --azul: #0b5d89;\n    --azul-claro: #eaf5fb;\n    --borda: #bccbd4;\n    --texto: #1f2f39;\n}\n\nhtml, body {\n    margin: 0;\n    padding: 0;\n    background: #f4f6f8;\n    font-family: Arial, Helvetica, sans-serif;\n    color: var(--texto);\n}\n\n/* TOOLBAR */\n\n.toolbar {\n    position: sticky;\n    top: 0;\n    z-index: 9999;\n    display: flex;\n    flex-wrap: wrap;\n    gap: 8px;\n    align-items: center;\n    padding: 10px 14px;\n    background: #ffffff;\n    border-bottom: 1px solid #d8e0e6;\n    box-shadow: 0 1px 5px rgba(0,0,0,.08);\n}\n\n.toolbar .btn { font-weight: 700; }\n\n.seletor-boletim-label {\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    font-size: 12px;\n    font-weight: 800;\n    color: #26343d;\n}\n\n.seletor-boletim-label select {\n    font-size: 12px;\n    font-weight: 700;\n}\n\n.status-msg {\n    margin-left: auto;\n    font-size: 12px;\n    font-weight: 700;\n    color: #4b5d68;\n}\n\n/* A4 RETRATO */\n\n.page {\n    position: relative;\n    width: 210mm;\n    min-height: 297mm;\n    margin: 14px auto;\n    background: #ffffff;\n    box-shadow: 0 2px 12px rgba(0,0,0,.12);\n    padding: 20px 26px 26px;\n}\n\n/* CABEÇALHO */\n\n.header {\n    display: grid;\n    grid-template-columns: 1fr 140px;\n    align-items: center;\n    gap: 10px;\n    border-bottom: 3px solid var(--azul);\n    padding-bottom: 10px;\n    margin-bottom: 14px;\n}\n\n.header h1 { margin: 0; font-size: 22px; color: var(--azul); }\n.header .subtitulo { font-size: 13.5px; font-weight: 700; letter-spacing: .5px; color: #526772; margin-top: 3px; }\n.header .situacao-geral { font-size: 13.5px; font-weight: 900; color: var(--texto); margin-top: 6px; }\n.header .situacao-geral span { color: var(--azul); }\n\n.logo-box {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    text-align: center;\n    font-weight: 900;\n    color: #005482;\n    font-size: 13px;\n    line-height: 1.1;\n}\n\n/* TÍTULOS DE SEÇÃO */\n\n.section-title {\n    color: #1F497D;\n    font-weight: 900;\n    font-size: 15px;\n    padding: 7px 10px;\n    margin-top: 18px;\n    margin-bottom: 8px;\n}\n\n/* TABELAS */\n\ntable { width: 100%; border-collapse: collapse; }\n\nth, td {\n    border: 1px solid var(--borda);\n    padding: 7px 9px;\n    font-size: 13.5px;\n}\n\nthead th {\n    background: var(--azul);\n    color: #fff;\n    font-weight: 900;\n    text-align: center;\n    font-size: 12.5px;\n    text-transform: lowercase;\n}\n\nthead th::first-letter { text-transform: uppercase; }\n\ntd[contenteditable=\"true\"], th[contenteditable=\"true\"] { cursor: text; }\n\n.tabela-eixo td:first-child { font-weight: 700; }\n.fonte-nota { font-size: 10px; vertical-align: super; }\n\n.cota-auto { background: #fff; }\n.cota-manual { background: #fff; }\n\n.tag-fonte {\n    display: inline-block;\n    font-size: 9.5px;\n    font-weight: 900;\n    border-radius: 3px;\n    padding: 1px 5px;\n    margin-left: 4px;\n    vertical-align: middle;\n}\n\n.tag-auto { background: #0d9488; color: #fff; }\n.tag-manual { background: #cbd5df; color: #26343d; }\n\n.var-up { color: #c0392b; font-weight: 900; }\n.var-down { color: #0b5d89; font-weight: 900; }\n.var-flat { color: #526772; font-weight: 900; }\n\n.nota-tabela {\n    font-size: 10.5px;\n    color: #64757f;\n    margin-top: 9px;\n    line-height: 1.35;\n}\n\n/* Dentro da nota, o \"(1)\"/\"(2)\" sobrescrito fica alto/desalinhado com vertical-align:super\n   (herdado de .fonte-nota) — text-top encaixa melhor no começo da linha. */\n.nota-tabela .fonte-nota { vertical-align: text-top; }\n\n.diagrama-sistema {\n    width: 100%;\n    border: 1px solid var(--borda);\n    display: block;\n    margin: 0 0 4px;\n}\n\n.page-landscape { width: 297mm; min-height: 210mm; }\n\n.diagrama-frame-wrap {\n    width: 100%;\n    height: 166mm;\n    overflow: hidden;\n    border: 1px solid var(--borda);\n    position: relative;\n    background: #fff;\n}\n\n.diagrama-frame-wrap iframe {\n    position: absolute;\n    top: -40px; /* valor inicial aproximado; recalculado com precisão por ajustarEscalaDiagrama() */\n    left: 0;\n    width: 1700px;\n    height: 1048px;\n    border: 0;\n    transform-origin: top left;\n}\n\n.diagrama-frame-wrap img { display: none; width: 100%; height: 100%; object-fit: contain; }\n\n/* Modo impressão: troca o iframe (cores clareadas pelo @media print do próprio SIBH)\n   pela captura estática colorida gerada via capturar-diagrama-ribeira */\n.diagrama-frame-wrap.modo-impressao iframe { display: none; }\n.diagrama-frame-wrap.modo-impressao img { display: block; }\n\n/* CARDS */\n\n.cards {\n    display: grid;\n    grid-template-columns: repeat(6, 1fr);\n    border: 1px solid var(--borda);\n    margin-top: 6px;\n}\n\n.card {\n    padding: 10px 4px;\n    text-align: center;\n    border-right: 1px solid var(--borda);\n}\n\n.card:last-child { border-right: 0; }\n\n.card .num { font-size: 29px; font-weight: 900; line-height: 1; }\n.card .lab { margin-top: 4px; font-size: 10.5px; font-weight: 900; }\n\n.c-blue .num { color: #1481b7; }\n.c-green .num { color: #4caf50; }\n.c-yellow .num { color: #e7a900; }\n.c-orange .num { color: #ef8500; }\n.c-purple .num { color: #8e44ad; }\n.c-red .num { color: #e33e35; }\n\n/* PROPAGAÇÃO */\n\n.propagacao th {\n    background: var(--azul-claro);\n    color: #07527a;\n    text-align: center;\n    height: 34px;\n    font-size: 12.5px;\n}\n\n.propagacao .status td {\n    color: #fff;\n    font-weight: 900;\n    text-align: center;\n    height: 30px;\n    font-size: 13px;\n}\n\n/* DIAGNÓSTICO */\n\n.diagnostico {\n    margin-top: 10px;\n    border: 1px solid #ef9f14;\n    background: #fffdf8;\n    padding: 8px 9px;\n    font-size: 13px;\n    line-height: 1.4;\n}\n\n.diagnostico strong { color: #e48a00; margin-right: 6px; }\n\n/* SÍNTESE */\n\n.sintese p { font-size: 13px; line-height: 1.55; margin: 0 0 8px; text-align: justify; }\n.sintese strong { color: inherit; }\n\n/* ACIMA DA COTA / TENDÊNCIA */\n\n.acima { background: #fff1ef; color: #e33e35; font-weight: 900; text-align: center; }\n.trend { color: #0d73a4; font-weight: 900; white-space: nowrap; text-align: center; }\n\n.tendencia-select {\n    width: 100%;\n    border: 1px solid var(--borda);\n    background: #fff;\n    font-weight: 900;\n    font-size: 12.5px;\n    padding: 3px 2px;\n    text-align: center;\n    text-align-last: center;\n    cursor: pointer;\n}\n.tendencia-select.var-up, .tendencia-select.var-down, .tendencia-select.var-flat { color: #0d73a4; }\n\n/* CAMPOS EDITÁVEIS */\n\n[contenteditable=\"true\"] { outline: none; cursor: text; }\n\ntd[contenteditable=\"true\"]:hover,\ndiv[contenteditable=\"true\"]:hover,\nspan[contenteditable=\"true\"]:hover,\nh1[contenteditable=\"true\"]:hover {\n    box-shadow: inset 0 0 0 1px rgba(11,93,137,.35);\n}\n\ntd[contenteditable=\"true\"]:focus,\ndiv[contenteditable=\"true\"]:focus,\nspan[contenteditable=\"true\"]:focus,\nh1[contenteditable=\"true\"]:focus {\n    background: #fff6bf !important;\n    box-shadow: inset 0 0 0 2px #e0b428;\n}\n\n/* CONTROLES */\n\n.table-controls { display: flex; justify-content: flex-end; gap: 7px; margin: 6px 0 4px; }\n\n.ref-datas-controls {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: flex-end;\n    gap: 14px;\n    margin: 6px 0 4px;\n    padding: 8px 10px;\n    background: var(--azul-claro);\n    border: 1px solid var(--borda);\n}\n\n.ref-datas-controls label {\n    display: flex;\n    flex-direction: column;\n    gap: 3px;\n    font-size: 10.5px;\n    font-weight: 800;\n    color: #07527a;\n}\n\ntable tbody tr { cursor: pointer; }\n\n@media print {\n    .ref-datas-controls, .table-controls { display: none !important; }\n}\n\n/* PDF */\n\n@page { size: A4 portrait; margin: 0; }\n@page landscape { size: A4 landscape; margin: 0; }\n\n@media print {\n    html, body { width: 210mm; margin: 0; background: #fff; }\n    .toolbar { display: none !important; }\n    .page {\n        width: 210mm;\n        min-height: 0;\n        margin: 0;\n        box-shadow: none;\n        padding: 7mm 11mm 8mm;\n    }\n    .page-landscape { width: 297mm; page: landscape; }\n    .page + .page { break-before: page; page-break-before: always; }\n    [contenteditable=\"true\"] { outline: none !important; box-shadow: none !important; }\n    .tendencia-select {\n        appearance: none;\n        -webkit-appearance: none;\n        border: none;\n        background: transparent;\n        padding: 0;\n    }\n\n    tr, .header, .cards, .propagacao, .diagnostico, .sintese p, .section-title {\n        break-inside: avoid;\n        page-break-inside: avoid;\n    }\n    thead { display: table-header-group; }\n\n    .header { padding-bottom: 4px; margin-bottom: 6px; }\n    .header h1 { font-size: 22px; }\n    #pagina2 .header h1 { font-size: 17px; }\n    .header .subtitulo { font-size: 11.5px; margin-top: 2px; }\n    .header .situacao-geral { font-size: 11.5px; margin-top: 3px; }\n    .section-title { font-size: 12.5px; padding: 2.5px 9px; margin-top: 4px; margin-bottom: 2px; }\n    th, td { padding: 2.5px 6px; font-size: 10.5px; }\n    thead th { font-size: 10.5px; }\n    .nota-tabela { font-size: 8.5px; margin-top: 7px; line-height: 1.25; }\n    .cards { margin-top: 4px; }\n    .card { padding: 7px 4px; }\n    .card .num { font-size: 23px; }\n    .card .lab { font-size: 9px; margin-top: 2px; }\n    .propagacao th { height: 26px; font-size: 11px; }\n    .propagacao .status td { height: 24px; font-size: 11.5px; }\n    .diagnostico { margin-top: 6px; padding: 7px 8px; font-size: 11.5px; }\n    .sintese p { font-size: 11.5px; line-height: 1.4; margin: 0 0 6px; }\n    .tag-fonte { display: none !important; }\n\n    .diagrama-frame-wrap {\n        height: 154mm;\n        break-inside: avoid;\n        page-break-inside: avoid;\n    }\n    .page-landscape .nota-tabela { margin-top: 3px; }\n}\n\n</style>\n</head>\n\n<body>\n\n<div class=\"toolbar\">\n    <label class=\"seletor-boletim-label\">Boletim:\n        <select id=\"seletorBoletim\" class=\"form-select form-select-sm\" onchange=\"trocarBoletim(this.value)\">\n            <option value=\"tiete\">Alto Tietê</option>\n            <option value=\"ribeira\" selected>Vale do Ribeira de Iguape</option>\n        </select>\n    </label>\n    <button class=\"btn btn-sm\" style=\"background:#0d9488;color:#fff;\" onclick=\"atualizarDadosAPI()\">Atualizar dados da API</button>\n    <button class=\"btn btn-sm btn-success\" onclick=\"salvarDados()\">Salvar alterações</button>\n    <button class=\"btn btn-sm btn-secondary\" onclick=\"carregarDados()\">Carregar salvo</button>\n    <button class=\"btn btn-sm\" style=\"background:#7b2cbf;color:#fff;\" onclick=\"baixarHTML()\">Baixar HTML atualizado</button>\n    <button class=\"btn btn-sm\" style=\"background:#0b5d89;color:#fff;\" onclick=\"gerarPDF()\">Gerar PDF</button>\n    <button class=\"btn btn-sm btn-light border\" onclick=\"restaurarPadrao()\">Restaurar original</button>\n    <span class=\"status-msg\" id=\"statusMsg\">Carregando dados da API do SIBH…</span>\n</div>\n\n\n<!-- =========================================================\n     PÁGINA 1 — ESTRUTURAS\n========================================================= -->\n\n<div class=\"page\" id=\"pagina1\">\n\n<header class=\"header\">\n<div>\n<h1 contenteditable=\"true\">SUMÁRIO EXECUTIVO</h1>\n<div class=\"subtitulo\" contenteditable=\"true\">OPERAÇÃO DE CONTROLE DE CHEIAS</div>\n<div class=\"situacao-geral\">SITUAÇÃO GERAL | <span contenteditable=\"true\" id=\"dataHoraGeral\">—</span></div>\n</div>\n<div class=\"logo-box\"><img src=\"img/spaguas.png\" alt=\"SP ÁGUAS\" style=\"width: 50%;\"></div>\n</header>\n\n<div class=\"section-title\" contenteditable=\"true\">BACIA DO RIO RIBEIRA DO IGUAPE: PRINCIPAIS CURSOS D'ÁGUA E ESTRUTURAS</div>\n\n<img class=\"diagrama-sistema\" src=\"img/diagrama_vale_do_ribeira.png\" alt=\"Esquema do sistema — Rio Ribeira de Iguape e afluentes\">\n\n<div class=\"section-title\" contenteditable=\"true\">CHUVA NA BACIA DO RIO RIBEIRA DO IGUAPE (UGRHI 11)</div>\n\n<table class=\"tabela-chuva\">\n<thead>\n<tr>\n<th contenteditable=\"true\">Últimas 3hrs (mm)</th>\n<th contenteditable=\"true\">Últimas 24hrs (mm)</th>\n<th contenteditable=\"true\">Previsão 24hrs (mm)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td class=\"cota-auto\" id=\"chuva-3h\" contenteditable=\"true\" style=\"text-align:center;\">— mm</td>\n<td class=\"cota-auto\" id=\"chuva-24h\" contenteditable=\"true\" style=\"text-align:center;\">— mm</td>\n<td class=\"cota-auto\" id=\"chuva-prev24h\" contenteditable=\"true\" style=\"text-align:center;\">— mm</td>\n</tr>\n</tbody>\n</table>\n<div class=\"nota-tabela\" contenteditable=\"true\">\nFontes: Previsão - Open-Meteo (média na área da UGRHI 11) | Chuva observada - rede telemétrica SP-ÁGUAS | Atualizado em <span id=\"chuvaAtualizadoEm\">—</span>\n</div>\n\n<div class=\"section-title\" contenteditable=\"true\">SITUAÇÃO ATUAL DE ESTRUTURAS DE INTERESSE</div>\n\n<table class=\"tabela-eixo\">\n<thead>\n<tr>\n<th contenteditable=\"true\" style=\"width:12%;\">Eixo</th>\n<th contenteditable=\"true\" style=\"width:22%;\">Estrutura</th>\n<th contenteditable=\"true\" style=\"width:12%;\">Volume útil (%)</th>\n<th contenteditable=\"true\" style=\"width:14%;\">Cota atual <sup class=\"fonte-nota\">(1)</sup> (m)</th>\n<th contenteditable=\"true\" style=\"width:14%;\">Vazão defluente (m³/s)</th>\n<th contenteditable=\"true\" style=\"width:13%;\">Variação (m) (últimas 24h)</th>\n<th contenteditable=\"true\" style=\"width:13%;\">Variação (m³/s) (últimas 24h)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td contenteditable=\"true\" style=\"white-space:nowrap;\">Rio Capivari</td>\n<td contenteditable=\"true\">Barragem Capivari</td>\n<td class=\"cota-manual\" contenteditable=\"true\">—</td>\n<td class=\"cota-manual\" contenteditable=\"true\">—</td>\n<td class=\"cota-manual\" contenteditable=\"true\">—</td>\n<td class=\"cota-manual\" contenteditable=\"true\">—</td>\n<td class=\"cota-manual\" contenteditable=\"true\">—</td>\n</tr>\n</tbody>\n</table>\n<div class=\"nota-tabela\" contenteditable=\"true\">\n<sup class=\"fonte-nota\">(1)</sup> Nível máximo de operação (m): 845,00; Nível máximo maximorum (m): 845,50. Fonte dos dados: COPEL.\n</div>\n\n<div class=\"section-title\" contenteditable=\"true\">SITUAÇÃO DOS BARRAMENTOS DE INTERESSE — UHEs/PCHs NAS CABECEIRAS DO RIO JUQUIÁ</div>\n\n<div class=\"table-controls\">\n    <button class=\"btn btn-sm btn-success\" onclick=\"adicionarLinha('tabelaBarramentos', 6)\">+ Adicionar linha</button>\n    <button class=\"btn btn-sm btn-danger\" onclick=\"excluirLinhaSelecionada('tabelaBarramentos')\">Excluir linha selecionada</button>\n    <button class=\"btn btn-sm btn-outline-primary\" onclick=\"adicionarColuna('tabelaBarramentos')\">+ Adicionar coluna</button>\n    <button class=\"btn btn-sm btn-outline-danger\" onclick=\"excluirColunaSelecionada('tabelaBarramentos')\">Excluir coluna selecionada</button>\n</div>\n\n<table class=\"main-table\" id=\"tabelaBarramentos\">\n<thead>\n<tr>\n<th contenteditable=\"true\" style=\"width:28%;\">PONTO</th>\n<th contenteditable=\"true\" style=\"width:15%;\">NÍVEL ANTERIOR</th>\n<th contenteditable=\"true\" style=\"width:15%;\">NÍVEL ATUAL</th>\n<th contenteditable=\"true\" style=\"width:13%;\">JUSANTE</th>\n<th contenteditable=\"true\" style=\"width:15%;\">VARIAÇÃO</th>\n<th contenteditable=\"true\" style=\"width:14%;\">TENDÊNCIA</th>\n</tr>\n</thead>\n<tbody id=\"corpoBarramentos\">\n</tbody>\n</table>\n<div class=\"nota-tabela\" contenteditable=\"true\">\nFonte: SIBH-SPÁGUAS / ANA\n</div>\n\n</div>\n\n\n<!-- =========================================================\n     PÁGINA 2 — PONTOS DE MONITORAMENTO\n========================================================= -->\n\n<div class=\"page\" id=\"pagina2\">\n\n<header class=\"header\">\n<div>\n<h1 contenteditable=\"true\">SITUAÇÃO DOS PONTOS DE MONITORAMENTO (NÍVEL)</h1>\n<div class=\"subtitulo\" contenteditable=\"true\">VALE DO RIBEIRA DE IGUAPE — DADOS AUTOMÁTICOS VIA API SIBH-SPÁGUAS</div>\n<div class=\"situacao-geral\">ATUALIZADO EM | <span contenteditable=\"true\" id=\"dataHoraPontos\">—</span></div>\n</div>\n<div class=\"logo-box\"><img src=\"img/spaguas.png\" alt=\"SP ÁGUAS\" style=\"width: 50%;\"></div>\n</header>\n\n<section class=\"cards\" id=\"cardsResumo\">\n<div class=\"card c-blue\"><div class=\"num\" contenteditable=\"true\" id=\"card-total\">8</div><div class=\"lab\" contenteditable=\"true\">PONTOS MONITORADOS</div></div>\n<div class=\"card c-green\"><div class=\"num\" contenteditable=\"true\" id=\"card-normal\">—</div><div class=\"lab\" contenteditable=\"true\">NORMAL</div></div>\n<div class=\"card c-yellow\"><div class=\"num\" contenteditable=\"true\" id=\"card-atencao\">—</div><div class=\"lab\" contenteditable=\"true\">ATENÇÃO</div></div>\n<div class=\"card c-orange\"><div class=\"num\" contenteditable=\"true\" id=\"card-alerta\">—</div><div class=\"lab\" contenteditable=\"true\">ALERTA</div></div>\n<div class=\"card c-purple\"><div class=\"num\" contenteditable=\"true\" id=\"card-emergencia\">—</div><div class=\"lab\" contenteditable=\"true\">EMERGÊNCIA</div></div>\n<div class=\"card c-red\"><div class=\"num\" contenteditable=\"true\" id=\"card-extrav\">—</div><div class=\"lab\" contenteditable=\"true\">EXTRAVASAMENTO</div></div>\n</section>\n\n<div class=\"section-title\" contenteditable=\"true\" style=\"margin-top:12px;\">LEITURA DO SISTEMA — PROPAGAÇÃO DA CHEIA NO VALE DO RIBEIRA</div>\n\n<table class=\"propagacao\" id=\"tabelaPropagacao\">\n<tr id=\"propHeaderRow\"></tr>\n<tr class=\"status\" id=\"propStatusRow\"></tr>\n</table>\n\n\n<div class=\"ref-datas-controls\">\n    <label>Referência 1 (boletim anterior)\n        <input type=\"datetime-local\" id=\"refData1\" class=\"form-control form-control-sm\">\n    </label>\n    <label>Referência 2 (boletim atual)\n        <input type=\"datetime-local\" id=\"refData2\" class=\"form-control form-control-sm\">\n    </label>\n    <button class=\"btn btn-sm\" style=\"background:#0d9488;color:#fff;font-weight:800;\" onclick=\"atualizarDadosAPI()\">Aplicar horários</button>\n</div>\n\n<table class=\"main-table\" id=\"tabelaPontosCriticos\" style=\"margin-top:8px;\">\n<thead>\n<tr>\n<th contenteditable=\"true\" style=\"width:32%;\">PONTOS CRÍTICOS</th>\n<th contenteditable=\"true\" style=\"width:14%;\" id=\"th-nivel1\">NÍVEL 07H/DATA</th>\n<th contenteditable=\"true\" style=\"width:14%;\" id=\"th-nivel2\">NÍVEL 13H/DATA</th>\n<th contenteditable=\"true\" style=\"width:13%;\">VARIAÇÃO</th>\n<th contenteditable=\"true\" style=\"width:13%;\">ACIMA DA COTA</th>\n<th contenteditable=\"true\" style=\"width:14%;\">TENDÊNCIA</th>\n</tr>\n</thead>\n<tbody id=\"corpoPontosCriticos\">\n</tbody>\n</table>\n\n<div class=\"diagnostico\">\n<strong contenteditable=\"true\">DIAGNÓSTICO EXECUTIVO</strong>\n<span contenteditable=\"true\" id=\"diagnosticoTexto\">Aguardando dados da API…</span>\n</div>\n\n<div class=\"section-title\" contenteditable=\"true\" style=\"margin-top:16px;\">SÍNTESE DA SITUAÇÃO NOS PONTOS COM EXTRAVASAMENTO</div>\n\n<div class=\"sintese\" id=\"sinteseTexto\" contenteditable=\"true\">\n<p>Aguardando dados da API…</p>\n</div>\n\n</div>\n\n\n<!-- =========================================================\n     PÁGINA 4 — DIAGRAMA UNIFILAR (PAISAGEM)\n========================================================= -->\n\n<div class=\"page page-landscape\" id=\"pagina4\">\n\n<header class=\"header\">\n<div>\n<h1 contenteditable=\"true\">DIAGRAMA UNIFILAR — RIO RIBEIRA DO IGUAPE E LITORAL SUL</h1>\n<div class=\"subtitulo\" contenteditable=\"true\">DIAGRAMA EM TEMPO REAL — PLATAFORMA SIBH-SPÁGUAS</div>\n<div class=\"situacao-geral\">FONTE | <span contenteditable=\"true\">apps.spaguas.sp.gov.br/sibh/diagramas — Diagrama Ribeira de Iguape</span></div>\n</div>\n<div class=\"logo-box\"><img src=\"img/spaguas.png\" alt=\"SP ÁGUAS\" style=\"width: 50%;\"></div>\n</header>\n\n<div class=\"diagrama-frame-wrap\" id=\"wrapDiagrama\">\n<iframe id=\"frameDiagrama\" src=\"https://apps.spaguas.sp.gov.br/sibh/diagramas/tiete_pinheiros/?vw=flow&amp;dg=ribeira-iguape&amp;bs=gigante\" title=\"Diagrama unifilar Rio Ribeira do Iguape e Litoral Sul\"></iframe>\n<img id=\"diagramaImg\" alt=\"Diagrama unifilar Rio Ribeira do Iguape e Litoral Sul (captura para impressão)\">\n</div>\n\n</div>\n\n\n<script>\n\n/* =========================================================\n   CONFIGURAÇÃO DAS ESTAÇÕES (IDs da API pública SIBH-SPÁGUAS)\n========================================================= */\n\n// \"ordemRio\": posição de cada ponto seguindo o curso do rio, de montante para jusante\n// (Ribeira → Barra do Turvo → Iporanga → Eldorado → Sete Barras → Juquiá → Registro →\n// Pariquera-Açu) — usada para ordenar a tabela de pontos críticos.\nconst ESTACOES_RIBEIRA = [\n    { id: 29794, prefix: \"5F-005\", nome: \"Ribeira (Ponte Divisa Estadual)\", curto: \"Ribeira – Ponte Divisa Estadual\", trecho: \"Rio Ribeira de Iguape\", ordemRio: 1 },\n    { id: 30854, prefix: \"5F-010\", nome: \"Barra do Turvo (R. Franco Filho)\", curto: \"Barra do Turvo\", trecho: \"Rio Turvo\", ordemRio: 2 },\n    { id: 33203, prefix: \"5F-019\", nome: \"Iporanga (R. dos Expedicionários)\", curto: \"Iporanga\", trecho: \"Rio Ribeira de Iguape\", ordemRio: 3 },\n    { id: 29791, prefix: \"5F-001\", nome: \"Eldorado (Av. Beira Rio)\", curto: \"Eldorado\", trecho: \"Rio Ribeira de Iguape\", ordemRio: 4 },\n    { id: 29726, prefix: \"4F-015\", nome: \"Sete Barras (Banana)\", curto: \"Sete Barras\", trecho: \"Rio Ribeira de Iguape\", ordemRio: 5 },\n    { id: 29728, prefix: \"4F-018\", nome: \"Juquiá (Estrada do Pouso Alto)\", curto: \"Juquiá\", trecho: \"Rio Juquiá\", ordemRio: 6 },\n    { id: 26243, prefix: \"4F-002\", nome: \"Registro (Rua Félix Aby Azar)\", curto: \"Registro\", trecho: \"Rio Ribeira de Iguape\", ordemRio: 7 },\n    { id: 1176,  prefix: \"4F-042\", nome: \"Pariquera-Açu (Jusante Jacupiranga)\", curto: \"Pariquera-Açu\", trecho: \"Rio Ribeira de Iguape\", ordemRio: 8 },\n];\n\n// Barramentos/reservatórios nas cabeceiras do Alto Juquiá (UHEs/PCHs) — mesma API de medições,\n// station_prefix_ids diferentes das estações fluviométricas do eixo principal.\n// jusanteId: station_prefix_id do posto de jusante de cada barramento (quando existe cadastro\n// na API) — usado para preencher a coluna JUSANTE com a vazão defluente (campo \"read_value\").\nconst ESTACOES_BARRAMENTOS = [\n    { id: 14508, prefix: \"81499100\", nome: \"Piedade (UHE Jurupara — Barramento)\", jusanteId: 14461 },\n    { id: 9508,  prefix: \"81499080\", nome: \"Juquiá (PCH Serraria — Barramento)\", jusanteId: 9570 },\n    { id: 9545,  prefix: \"81500080\", nome: \"Juquiá (UHE Salto do Iporanga — Barramento)\", jusanteId: 9490 },\n    { id: 14480, prefix: \"81496080\", nome: \"Tapiraí (UHE Barra — Barramento)\", jusanteId: 14868 },\n    { id: 14473, prefix: \"81497080\", nome: \"Tapiraí (PCH Porto Raso — Barramento)\", jusanteId: null },\n    { id: 14437, prefix: \"81498080\", nome: \"Tapiraí (UHE Alecrim — Barramento)\", jusanteId: null },\n    { id: 14504, prefix: \"81491080\", nome: \"Juquitiba (UHE França — Barramento)\", jusanteId: 14546 },\n    { id: 14815, prefix: \"81495080\", nome: \"Ibiúna (UHE Fumaça — Barramento)\", jusanteId: null },\n];\n\n// station_prefix_id das 6 estações do eixo principal, mapeadas na tabela de propagação\nconst PROPAGACAO_IDS = {\n    \"prop-ribeira\": 29794, \"prop-iporanga\": 33203, \"prop-eldorado\": 29791,\n    \"prop-setebarras\": 29726, \"prop-registro\": 26243, \"prop-pariquera\": 1176,\n};\n\n// A partir daqui, as chamadas à API do SIBH passam pelo proxy local (api-sibh),\n// em vez de ir direto do navegador — evita falhas de fetch por CORS/rede/proxy do lado\n// de quem acessa a página, e permite configurar um IP de saída fixo no PHP se precisar.\nconst PARAMS_URL = \"api-sibh?path=parameters\";\nconst MEDICOES_URL = \"api-sibh?path=measurements\";\nconst MEDICOES_NOW_URL = \"api-sibh?path=measurements/now\";\n\n// Guarda o resultado calculado na última atualização (e as referências de data/hora usadas),\n// para permitir recalcular o diagnóstico/síntese quando a TENDÊNCIA é alterada manualmente,\n// sem precisar consultar a API de novo.\nlet ESTADO_ATUAL = { resultados: null, alvo1: null, alvo2: null };\n\n// station_prefix_id de todas as estações pluviométricas da UGRHI 11 (Ribeira de Iguape / Litoral Sul),\n// levantadas a partir do cadastro de estações do SIBH (station.ugrhi.cod === 11).\nconst UGRHI11_PLUVIOMETRICAS = [15028,35724,35728,35726,35729,33199,741,35523,35731,35732,35734,35730,35735,33193,1538,29423,29426,33340,35701,29480,33487,15140,622,29435,63,35534,1321,1187,33488,1319,27975,29406,29446,86,29394,33196,463,35541,29455,9617,29401,29273,33288,29495,29445,33285,29473,26100,29429,1149,29413,1100,26097,1273,1295,1131,31259,29397,1120,29414,33218,35532,33595,31258,29453,740,25472,29461,33354,29430,35546,29460,25869,33466,29471,33593,1192,15141,29301,15137,29462,29396,9509,29400,1346,33415,29439,9546,29441,29493,33286,29431,29405,35545,29456,29457,29395,29442,33436,29469,29420,31265,29274,1171,29399,29436,29422,31260,29417,462,29408,33284,9544,35525,35661,26105,29404,31263,29438,29449,35733,33418,1191,1389,29403,71,31207,1196,29185,29459,623,1125,33523,1135,29437,35725,29463,29415,29433,15136,1256,31264,29484,29283,29425,31262,15044,35736,193,33219,464,29409,29424,29452,35727,29492,26096,29474,29391,29440,29491,29494,29475,29470,29215,29428,29434,33162,29427,1197,27097,29412,29411,29472,25514,15147,1500,1532,15162,9523,9689,33486,29398,15170,25531,1340,33428,33508,1522,27939,25461,29410,73,29402,1540,29418,29476,33594,1375,29276,33422,33202,9552,1487,65,67,33226,29468,33204,29419,33442,33519,33369,739,467,15144,15145,473,33373,29432,35658,738,170,1284,35543,1177,15252,192,1505,118,35662,184,35692,15138];\n\n/* =========================================================\n   UTILITÁRIOS\n========================================================= */\n\nfunction mensagem(texto, cor = \"#4b5d68\") {\n    const el = document.getElementById(\"statusMsg\");\n    if (el) { el.textContent = texto; el.style.color = cor; }\n}\n\nfunction trocarBoletim(valor) {\n    if (valor === \"tiete\") {\n        window.location.href = \"sumario_executivo_tiete_pinheiros.html\";\n    }\n}\n\n// Captura uma screenshot nova do diagrama do Ribeira (troca de diagrama exige clique\n// dentro da própria página do SIBH, então não dá pra fazer isso com um iframe ao vivo)\n// e só então abre a impressão.\nasync function gerarPDF() {\n    const wrap = document.getElementById(\"wrapDiagrama\");\n    const img = document.getElementById(\"diagramaImg\");\n\n    mensagem(\"Capturando diagrama em cores para o PDF (~35s)…\", \"#0d9488\");\n    try {\n        const resp = await fetch(\"capturar-diagrama-ribeira\");\n        const data = await resp.json();\n        if (data.success) {\n            await new Promise((resolve, reject) => {\n                img.onload = resolve;\n                img.onerror = reject;\n                img.src = data.path + \"?t=\" + Date.now();\n            });\n            wrap.classList.add(\"modo-impressao\");\n            mensagem(\"Diagrama capturado. Abrindo impressão…\", \"#198754\");\n        } else {\n            mensagem(\"Não foi possível capturar o diagrama em cores (\" + (data.error || \"erro desconhecido\") + \"). Imprimindo com o diagrama ao vivo.\", \"#b26a00\");\n        }\n    } catch (erro) {\n        mensagem(\"Falha ao capturar o diagrama (\" + erro.message + \"). Imprimindo com o diagrama ao vivo.\", \"#b26a00\");\n    }\n    window.print();\n}\n\nwindow.addEventListener(\"afterprint\", function () {\n    const wrap = document.getElementById(\"wrapDiagrama\");\n    if (wrap) wrap.classList.remove(\"modo-impressao\");\n});\n\n// Altura (em px, na escala original 1700x1048 do iframe) do topo a recortar — remove só o\n// menu do site SIBH, mantendo visível a barra \"Diagrama Ribeira de Iguape\". Igual ao clip\n// \"y\" usado em capture_diagrama_ribeira.js, para a versão impressa bater com a tela.\nconst RECORTE_TOPO_IFRAME = 64;\n\nfunction ajustarEscalaDiagrama() {\n    const wrap = document.getElementById(\"wrapDiagrama\");\n    const frame = document.getElementById(\"frameDiagrama\");\n    if (!wrap || !frame) return;\n    const larguraIframe = 1700, alturaIframe = 1048;\n    // Cabe na largura E na altura da moldura: a legenda do SIBH fica fixa no rodapé do iframe\n    // e era cortada quando só a largura definia a escala (folha paisagem do PDF é mais baixa).\n    const alturaVisivel = alturaIframe - RECORTE_TOPO_IFRAME;\n    const escala = Math.min(wrap.clientWidth / larguraIframe, wrap.clientHeight / alturaVisivel);\n    frame.style.transform = \"scale(\" + escala + \")\";\n    frame.style.top = \"-\" + (RECORTE_TOPO_IFRAME * escala) + \"px\";\n    frame.style.left = ((wrap.clientWidth - larguraIframe * escala) / 2) + \"px\"; // centraliza a sobra\n}\n\nwindow.addEventListener(\"resize\", ajustarEscalaDiagrama);\nwindow.addEventListener(\"beforeprint\", ajustarEscalaDiagrama);\n// Recalcula com as medidas do layout de impressão (e volta às da tela depois)\nwindow.matchMedia(\"print\").addEventListener(\"change\", ajustarEscalaDiagrama);\n\nfunction fmt(n, casas = 2) {\n    if (n === null || n === undefined || isNaN(n)) return \"—\";\n    const fator = Math.pow(10, casas);\n    const arredondado = Math.round(n * fator) / fator;\n    return arredondado.toLocaleString(\"pt-BR\", { minimumFractionDigits: casas, maximumFractionDigits: casas });\n}\n\nfunction fmtSinal(n, casas = 2) {\n    if (n === null || n === undefined || isNaN(n)) return \"—\";\n    const s = n > 0 ? \"+\" : (n < 0 ? \"\" : \"\");\n    return s + fmt(n, casas);\n}\n\nfunction dataHoraBRT_paraUTC(diaOffset, hora) {\n    const agora = new Date();\n    const brtAgora = new Date(agora.getTime() - 3 * 3600 * 1000);\n    const ano = brtAgora.getUTCFullYear();\n    const mes = brtAgora.getUTCMonth();\n    const dia = brtAgora.getUTCDate() + diaOffset;\n    return new Date(Date.UTC(ano, mes, dia, hora + 3, 0, 0));\n}\n\nfunction paraBRT(dataUTC) { return new Date(dataUTC.getTime() - 3 * 3600 * 1000); }\n\nfunction formataDataBR(dataUTC) {\n    const brt = paraBRT(dataUTC);\n    const dd = String(brt.getUTCDate()).padStart(2, \"0\");\n    const mm = String(brt.getUTCMonth() + 1).padStart(2, \"0\");\n    return dd + \"/\" + mm;\n}\n\nfunction formataHoraBR(dataUTC) {\n    const brt = paraBRT(dataUTC);\n    return String(brt.getUTCHours()).padStart(2, \"0\") + \"h\";\n}\n\nfunction formataHoraMinBR(dataUTC) {\n    const brt = paraBRT(dataUTC);\n    return String(brt.getUTCHours()).padStart(2, \"0\") + \"h\" + String(brt.getUTCMinutes()).padStart(2, \"0\");\n}\n\n// Procura, dentro do histórico buscado (medicoesLongas), desde quando a estação está\n// ininterruptamente na mesma situação (statusAtual) que apresenta agora — caminha para trás\n// a partir da leitura mais próxima de alvoUTC até encontrar uma leitura com status diferente.\n// Retorna:\n//   - null se não houver nenhum dado para a estação;\n//   - a string \"LIMITE\" se o histórico buscado acabar antes de encontrar a transição\n//     (ou seja, a entrada na situação atual aconteceu antes do início da janela buscada —\n//     não dá pra afirmar a data/hora exatas, então o texto deve mostrar \"[PREENCHER]\");\n//   - a Date exata da transição, quando encontrada dentro da janela.\nfunction encontrarInicioStatus(medicoesLongas, id, par, statusAtual, alvoUTC) {\n    const serie = medicoesLongas.filter(m => m.station_prefix_id === id).sort((a, b) => new Date(a.date) - new Date(b.date));\n    if (serie.length === 0) return null;\n    let idxAlvo = 0, menorDiff = Infinity;\n    serie.forEach((m, i) => {\n        const diff = Math.abs(new Date(m.date) - alvoUTC);\n        if (diff < menorDiff) { menorDiff = diff; idxAlvo = i; }\n    });\n    let inicio = serie[idxAlvo];\n    let transicaoEncontrada = false;\n    for (let i = idxAlvo; i >= 0; i--) {\n        if (classificarStatus(serie[i].value / 100, par) !== statusAtual) { transicaoEncontrada = true; break; }\n        inicio = serie[i];\n    }\n    if (!transicaoEncontrada) return \"LIMITE\";\n    return new Date(inicio.date);\n}\n\n// Se a estação NÃO está em extravasamento agora, mas esteve em algum momento nas últimas\n// 24 horas, retorna a data/hora aproximada em que ela saiu dessa condição (a leitura logo\n// após a última leitura em extravasamento dentro dessa janela). Retorna null se a estação\n// está em extravasamento agora, ou se não esteve em extravasamento nas últimas 24h.\nfunction encontrarSaidaExtravasamento(medicoesLongas, id, par, statusAtual, alvoUTC) {\n    if (statusAtual === \"EXTRAVASAMENTO\") return null;\n\n    const serie = medicoesLongas.filter(m => m.station_prefix_id === id).sort((a, b) => new Date(a.date) - new Date(b.date));\n    if (serie.length === 0) return null;\n\n    let idxAlvo = 0, menorDiff = Infinity;\n    serie.forEach((m, i) => {\n        const diff = Math.abs(new Date(m.date) - alvoUTC);\n        if (diff < menorDiff) { menorDiff = diff; idxAlvo = i; }\n    });\n\n    const limite24h = new Date(alvoUTC.getTime() - 24 * 3600 * 1000);\n\n    for (let i = idxAlvo; i >= 0; i--) {\n        const dataLeitura = new Date(serie[i].date);\n        if (dataLeitura < limite24h) break;\n        if (classificarStatus(serie[i].value / 100, par) === \"EXTRAVASAMENTO\") {\n            const saida = serie[i + 1] || serie[i];\n            return new Date(saida.date);\n        }\n    }\n    return null;\n}\n\nfunction formataReferenciaTxt(dataUTC, outraReferenciaUTC) {\n    const hora = formataHoraBR(dataUTC);\n    if (!outraReferenciaUTC) return hora;\n    const mesmodia = formataDataBR(dataUTC) === formataDataBR(outraReferenciaUTC);\n    return mesmodia ? hora : (hora + \" de \" + formataDataBR(dataUTC));\n}\n\nfunction parseDatetimeLocalBRTparaUTC(valor) {\n    if (!valor) return null;\n    const [dataParte, horaParte] = valor.split(\"T\");\n    const [ano, mes, dia] = dataParte.split(\"-\").map(Number);\n    const [hora, minuto] = horaParte.split(\":\").map(Number);\n    return new Date(Date.UTC(ano, mes - 1, dia, hora + 3, minuto || 0, 0));\n}\n\nfunction paraDatetimeLocalBRT(dataUTC) {\n    const brt = paraBRT(dataUTC);\n    const ano = brt.getUTCFullYear();\n    const mes = String(brt.getUTCMonth() + 1).padStart(2, \"0\");\n    const dia = String(brt.getUTCDate()).padStart(2, \"0\");\n    const hora = String(brt.getUTCHours()).padStart(2, \"0\");\n    const min = String(brt.getUTCMinutes()).padStart(2, \"0\");\n    return ano + \"-\" + mes + \"-\" + dia + \"T\" + hora + \":\" + min;\n}\n\nfunction inicializarCamposReferencia() {\n    const ref1 = document.getElementById(\"refData1\");\n    const ref2 = document.getElementById(\"refData2\");\n    if (ref1 && !ref1.value) ref1.value = paraDatetimeLocalBRT(dataHoraBRT_paraUTC(0, 7));\n    if (ref2 && !ref2.value) ref2.value = paraDatetimeLocalBRT(new Date());\n}\n\n// \"AAAA/MM/DD HH:mm\" (API v2, já em UTC) -> instante UTC\nfunction parseDataV2ParaUTC(str) {\n    const [dataParte, horaParte] = str.split(\" \");\n    const [ano, mes, dia] = dataParte.split(\"/\").map(Number);\n    const [hora, min] = horaParte.split(\":\").map(Number);\n    return new Date(Date.UTC(ano, mes - 1, dia, hora, min, 0));\n}\n\nfunction extrairLeituras(medicoes, id, dataAlvoUTC) {\n    const doId = medicoes.filter(m => m.station_prefix_id === id).sort((a, b) => new Date(a.date) - new Date(b.date));\n    if (doId.length === 0) return { alvo: null, recente: null };\n    let alvo = null, menorDiff = Infinity;\n    doId.forEach(m => {\n        const diff = Math.abs(new Date(m.date) - dataAlvoUTC);\n        if (diff < menorDiff) { menorDiff = diff; alvo = m; }\n    });\n    const recente = doId[doId.length - 1];\n    return { alvo, recente };\n}\n\n// Arredonda para 2 casas — a classificação de tendência usa o valor JÁ ARREDONDADO\n// (o mesmo que aparece na tela), então 0,00 é sempre \"Estável\", e qualquer variação\n// visível (mesmo 0,01) já conta como Subida/Queda.\nfunction arred2(n) {\n    return Math.round(n * 100) / 100;\n}\n\nfunction tendenciaTexto(variacao) {\n    if (variacao === null || isNaN(variacao)) return \"—\";\n    const v = arred2(variacao);\n    if (v > 0) return \"↑ Subida\";\n    if (v < 0) return \"↓ Queda\";\n    return \"→ Estável\";\n}\n\nfunction classeTendencia(variacao) {\n    if (variacao === null || isNaN(variacao)) return \"\";\n    const v = arred2(variacao);\n    if (v > 0) return \"var-up\";\n    if (v < 0) return \"var-down\";\n    return \"var-flat\";\n}\n\n// Tendência \"efetiva\" de um ponto: usa o valor escolhido manualmente no select da coluna\n// TENDÊNCIA (r.tendenciaManual), se houver; caso contrário, calcula a partir da variação numérica.\n// Chaves internas: \"subida\" | \"descida\" | \"estavel\" | null (sem dado).\nfunction tendenciaEfetiva(r) {\n    if (r.tendenciaManual === \"subida\" || r.tendenciaManual === \"descida\" || r.tendenciaManual === \"estavel\") {\n        return r.tendenciaManual;\n    }\n    if (r.variacao === null || r.variacao === undefined || isNaN(r.variacao)) return null;\n    const v = arred2(r.variacao);\n    if (v > 0) return \"subida\";\n    if (v < 0) return \"descida\";\n    return \"estavel\";\n}\n\nfunction tendenciaTextoEfetiva(r) {\n    const t = tendenciaEfetiva(r);\n    if (t === \"subida\") return \"↑ Subida\";\n    if (t === \"descida\") return \"↓ Queda\";\n    if (t === \"estavel\") return \"→ Estável\";\n    return \"—\";\n}\n\nfunction classeTendenciaEfetiva(r) {\n    const t = tendenciaEfetiva(r);\n    if (t === \"subida\") return \"var-up\";\n    if (t === \"descida\") return \"var-down\";\n    if (t === \"estavel\") return \"var-flat\";\n    return \"\";\n}\n\n// Chamado pelo <select> da coluna TENDÊNCIA quando o usuário altera manualmente a tendência\n// de um ponto — recalcula na hora o texto do diagnóstico/síntese com o novo valor.\nfunction alterarTendenciaManual(selectEl) {\n    const id = Number(selectEl.dataset.id);\n    const resultados = ESTADO_ATUAL.resultados || [];\n    const r = resultados.find(x => x.id === id);\n    if (!r) return;\n    r.tendenciaManual = selectEl.value || null;\n    selectEl.className = \"tendencia-select \" + classeTendenciaEfetiva(r);\n    if (ESTADO_ATUAL.alvo1 && ESTADO_ATUAL.alvo2) {\n        gerarDiagnosticoESintese(resultados, ESTADO_ATUAL.alvo1, ESTADO_ATUAL.alvo2);\n    }\n    mensagem(\"Tendência atualizada manualmente. Diagnóstico e síntese recalculados.\", \"#198754\");\n}\n\nasync function buscarParametros(ids) {\n    const params = new URLSearchParams();\n    ids.forEach(id => params.append(\"parameterizable_ids[]\", id));\n    params.append(\"parameterizable_type\", \"StationPrefix\");\n    params.append(\"parameter_type_id\", \"2\");\n\n    const resp = await fetch(PARAMS_URL + \"&\" + params.toString());\n    if (!resp.ok) throw new Error(\"HTTP \" + resp.status);\n    const data = await resp.json();\n\n    const converte = (x) => {\n        const n = parseFloat(x);\n        return (x !== undefined && x !== null && x !== \"\" && !isNaN(n)) ? n / 100 : null;\n    };\n\n    const mapa = {};\n    data.forEach(item => {\n        const v = item.values || {};\n        mapa[Number(item.parameterizable_id)] = {\n            atencao: converte(v.attention),\n            alerta: converte(v.alert),\n            emergencia: converte(v.emergency),\n            extravasamento: converte(v.extravasation),\n        };\n    });\n    return mapa;\n}\n\n// API v2 — measurements por período explícito (start_date/end_date), granularidade \"minute\"\n// (a cada ~10 min), o que dá leituras instantâneas em vez de médias por hora.\nasync function buscarMedicoes(ids, horas = 72) {\n    const fim = new Date();\n    const inicio = new Date(fim.getTime() - horas * 3600 * 1000);\n    const params = new URLSearchParams();\n    ids.forEach(id => params.append(\"station_prefix_ids[]\", id));\n    params.append(\"start_date\", inicio.toISOString());\n    params.append(\"end_date\", fim.toISOString());\n    params.append(\"group_type\", \"minute\");\n\n    const resp = await fetch(MEDICOES_URL + \"&\" + params.toString());\n    if (!resp.ok) throw new Error(\"HTTP \" + resp.status);\n    const data = await resp.json();\n\n    return (data.measurements || []).map(m => ({\n        station_prefix_id: Number(m.station_prefix_id),\n        value: m.value,\n        read_value: m.read_value,\n        date: parseDataV2ParaUTC(m.date).toISOString(),\n    }));\n}\n\n// Chuva média na UGRHI 11 (API v2 pública, com CORS liberado).\nasync function mediaChuvaUGRHI11(horas) {\n    const url = MEDICOES_NOW_URL + \"&station_type_id=2&hours=\" + horas;\n    const resp = await fetch(url);\n    if (!resp.ok) throw new Error(\"HTTP \" + resp.status);\n    const data = await resp.json();\n    const medicoes = data.measurements || [];\n    const idsSet = new Set(UGRHI11_PLUVIOMETRICAS);\n    const daUgrhi = medicoes.filter(m => idsSet.has(Number(m.station_prefix_id)) && m.value !== null && !isNaN(m.value));\n    if (daUgrhi.length === 0) return null;\n    const soma = daUgrhi.reduce((acc, m) => acc + Math.max(0, m.value), 0);\n    return { media: soma / daUgrhi.length, qtdEstacoes: daUgrhi.length };\n}\n\nasync function atualizarChuvaUGRHI11(referencia) {\n    const el3h = document.getElementById(\"chuva-3h\");\n    const el24h = document.getElementById(\"chuva-24h\");\n    const elAtualizado = document.getElementById(\"chuvaAtualizadoEm\");\n    try {\n        const [r3h, r24h] = await Promise.all([mediaChuvaUGRHI11(3), mediaChuvaUGRHI11(24)]);\n        if (el3h) el3h.textContent = r3h ? fmt(r3h.media, 1) + \" mm\" : \"—\";\n        if (el24h) el24h.textContent = r24h ? fmt(r24h.media, 1) + \" mm\" : \"—\";\n        if (elAtualizado) {\n            const ref = paraBRT(referencia || new Date());\n            const dd = String(ref.getUTCDate()).padStart(2, \"0\");\n            const mm = String(ref.getUTCMonth() + 1).padStart(2, \"0\");\n            const hh = String(ref.getUTCHours()).padStart(2, \"0\");\n            const min = String(ref.getUTCMinutes()).padStart(2, \"0\");\n            elAtualizado.textContent = dd + \"/\" + mm + \"/\" + ref.getUTCFullYear() + \" - \" + hh + \":\" + min;\n        }\n    } catch (erro) {\n        console.error(\"Falha ao buscar chuva UGRHI 11:\", erro);\n        if (el3h) el3h.textContent = \"—\";\n        if (el24h) el24h.textContent = \"—\";\n    }\n}\n\n/* =========================================================\n   PREVISÃO DE CHUVA 24H NA UGRHI 11 (Open-Meteo)\n   Grade de pontos dentro do contorno dos 23 municípios da UGRHI 11 (geo/ugrhi11_municipios.geojson,\n   extraído de geo/SP_Municipios_39.geojson); a previsão é a média da chuva acumulada\n   nas 24h seguintes ao horário de referência em todos os pontos da grade.\n========================================================= */\n\nconst UGRHI11_GEOJSON_URL = \"geo/ugrhi11_municipios.geojson\";\nconst PASSO_GRADE_PREVISAO = 0.1; // graus (~11 km)\n\n// Ray casting: o ponto está dentro do polígono (anel externo menos buracos)?\nfunction pontoNoAnel(x, y, anel) {\n    let dentro = false;\n    for (let i = 0, j = anel.length - 1; i < anel.length; j = i++) {\n        const [xi, yi] = anel[i], [xj, yj] = anel[j];\n        if ((yi > y) !== (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) dentro = !dentro;\n    }\n    return dentro;\n}\n\nfunction pontoNaGeometria(x, y, geometria) {\n    const poligonos = geometria.type === \"MultiPolygon\" ? geometria.coordinates : [geometria.coordinates];\n    return poligonos.some(([externo, ...buracos]) =>\n        pontoNoAnel(x, y, externo) && !buracos.some(b => pontoNoAnel(x, y, b)));\n}\n\n// Pontos (centros das células da grade) que caem dentro de algum município da UGRHI 11\nasync function pontosGradeUGRHI11() {\n    const resp = await fetch(UGRHI11_GEOJSON_URL);\n    if (!resp.ok) throw new Error(\"GeoJSON UGRHI 11: HTTP \" + resp.status);\n    const geometrias = (await resp.json()).features.map(f => f.geometry);\n\n    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;\n    geometrias.forEach(g => (g.type === \"MultiPolygon\" ? g.coordinates : [g.coordinates])\n        .forEach(p => p[0].forEach(([x, y]) => {\n            minX = Math.min(minX, x); maxX = Math.max(maxX, x);\n            minY = Math.min(minY, y); maxY = Math.max(maxY, y);\n        })));\n\n    const pontos = [];\n    for (let y = minY + PASSO_GRADE_PREVISAO / 2; y < maxY; y += PASSO_GRADE_PREVISAO) {\n        for (let x = minX + PASSO_GRADE_PREVISAO / 2; x < maxX; x += PASSO_GRADE_PREVISAO) {\n            if (geometrias.some(g => pontoNaGeometria(x, y, g))) pontos.push([+y.toFixed(4), +x.toFixed(4)]);\n        }\n    }\n    return pontos;\n}\n\n// \"AAAA-MM-DDTHH:00\" no horário de Brasília (formato de start_hour/end_hour do Open-Meteo)\nfunction horaBRTiso(dataUTC) {\n    const d = paraBRT(dataUTC);\n    return d.getUTCFullYear() + \"-\" + String(d.getUTCMonth() + 1).padStart(2, \"0\") + \"-\" +\n        String(d.getUTCDate()).padStart(2, \"0\") + \"T\" + String(d.getUTCHours()).padStart(2, \"0\") + \":00\";\n}\n\nasync function previsaoChuvaUGRHI11_24h(referencia) {\n    const pontos = await pontosGradeUGRHI11();\n    if (pontos.length === 0) return null;\n\n    // Precipitação horária do Open-Meteo é o acumulado da hora anterior: as 24h seguintes à\n    // hora cheia de referência H são os valores de H+1 até H+24.\n    const base = new Date(referencia || new Date());\n    base.setUTCMinutes(0, 0, 0);\n    const inicio = new Date(base.getTime() + 3600 * 1000);\n    const fim = new Date(base.getTime() + 24 * 3600 * 1000);\n\n    const url = \"https://api.open-meteo.com/v1/forecast\" +\n        \"?latitude=\" + pontos.map(p => p[0]).join(\",\") +\n        \"&longitude=\" + pontos.map(p => p[1]).join(\",\") +\n        \"&hourly=precipitation&timezone=America%2FSao_Paulo\" +\n        \"&start_hour=\" + horaBRTiso(inicio) + \"&end_hour=\" + horaBRTiso(fim);\n    const resp = await fetch(url);\n    if (!resp.ok) throw new Error(\"Open-Meteo: HTTP \" + resp.status);\n    const dados = await resp.json();\n    const locais = Array.isArray(dados) ? dados : [dados];\n\n    const acumulados = locais\n        .map(l => (l.hourly && l.hourly.precipitation) || [])\n        .filter(serie => serie.some(v => v !== null))\n        .map(serie => serie.reduce((acc, v) => acc + (v || 0), 0));\n    if (acumulados.length === 0) return null;\n    return { media: acumulados.reduce((a, b) => a + b, 0) / acumulados.length, qtdPontos: acumulados.length };\n}\n\nasync function atualizarPrevisaoUGRHI11(referencia) {\n    const el = document.getElementById(\"chuva-prev24h\");\n    if (!el) return;\n    try {\n        const r = await previsaoChuvaUGRHI11_24h(referencia);\n        el.textContent = r ? fmt(r.media, 1) + \" mm\" : \"—\";\n    } catch (erro) {\n        console.error(\"Falha ao buscar previsão UGRHI 11:\", erro);\n        el.textContent = \"—\";\n    }\n}\n\nfunction classificarStatus(nivel, par) {\n    if (nivel === null || !par) return \"NORMAL\";\n    if (par.extravasamento !== null && nivel >= par.extravasamento) return \"EXTRAVASAMENTO\";\n    if (par.emergencia !== null && nivel >= par.emergencia) return \"EMERGÊNCIA\";\n    if (par.alerta !== null && nivel >= par.alerta) return \"ALERTA\";\n    if (par.atencao !== null && nivel >= par.atencao) return \"ATENÇÃO\";\n    return \"NORMAL\";\n}\n\nfunction corStatus(status) {\n    if (status === \"EXTRAVASAMENTO\") return \"background:#e63946;color:#fff;font-weight:900;\";\n    if (status === \"EMERGÊNCIA\") return \"background:#8e44ad;color:#fff;font-weight:900;\";\n    if (status === \"ALERTA\") return \"background:#ef8500;color:#fff;font-weight:900;\";\n    if (status === \"ATENÇÃO\") return \"background:#d4ac0d;color:#fff;font-weight:900;\";\n    return \"background:#1abc9c;color:#fff;font-weight:900;\";\n}\n\n// Cor de texto (sem fundo colorido) para o nome da estação na síntese — usada com um\n// realce cinza padrão igual para todos os status.\nfunction corTextoStatus(status) {\n    if (status === \"EXTRAVASAMENTO\") return \"#c0392b\";\n    if (status === \"EMERGÊNCIA\") return \"#8e44ad\";\n    if (status === \"ALERTA\") return \"#c9700a\";\n    if (status === \"ATENÇÃO\") return \"#a3820a\";\n    return \"#0d9488\";\n}\n\nfunction aplicarCorPropagacao(el, status) {\n    if (status === \"EXTRAVASAMENTO\") { el.style.background = \"#f44336\"; el.style.color = \"#fff\"; }\n    else if (status === \"EMERGÊNCIA\") { el.style.background = \"#8e44ad\"; el.style.color = \"#fff\"; }\n    else if (status === \"ALERTA\") { el.style.background = \"#ef8500\"; el.style.color = \"#fff\"; }\n    else if (status === \"ATENÇÃO\") { el.style.background = \"#f4b400\"; el.style.color = \"#fff\"; }\n    else if (status === \"NORMAL\") { el.style.background = \"#4caf50\"; el.style.color = \"#fff\"; }\n    else { el.style.background = \"#9aa7ae\"; el.style.color = \"#fff\"; }\n}\n\n/* =========================================================\n   ATUALIZAÇÃO PRINCIPAL\n========================================================= */\n\nasync function atualizarDadosAPI() {\n    mensagem(\"Consultando API do SIBH-SPÁGUAS…\", \"#0d9488\");\n\n    const frameDiagrama = document.getElementById(\"frameDiagrama\");\n    if (frameDiagrama) frameDiagrama.src = frameDiagrama.src;\n    ajustarEscalaDiagrama();\n\n    inicializarCamposReferencia();\n\n    try {\n        const ids = ESTACOES_RIBEIRA.map(p => p.id);\n        const idsBarramentos = ESTACOES_BARRAMENTOS.map(p => p.id);\n        const idsJusante = ESTACOES_BARRAMENTOS.map(p => p.jusanteId).filter(id => id !== null);\n        const [medicoes, parametros, medicoesBarr, medicoesJusante, medicoesLongas] = await Promise.all([\n            buscarMedicoes(ids, 72),\n            buscarParametros(ids),\n            buscarMedicoes(idsBarramentos, 72),\n            idsJusante.length ? buscarMedicoes(idsJusante, 72) : Promise.resolve([]),\n            // Janela usada para descobrir desde quando cada ponto está na situação atual\n            // (procura a transição de status mais recente no histórico). Regra: se a entrada em\n            // extravasamento não for encontrada dentro dessa janela (168h = 7 dias), mostra\n            // \"[PREENCHER]\" em vez de aproximar.\n            buscarMedicoes(ids, 168),\n        ]);\n\n        const ref1Input = document.getElementById(\"refData1\");\n        const ref2Input = document.getElementById(\"refData2\");\n        const alvo1 = (ref1Input && ref1Input.value) ? parseDatetimeLocalBRTparaUTC(ref1Input.value) : dataHoraBRT_paraUTC(0, 7);\n        const alvo2 = (ref2Input && ref2Input.value) ? parseDatetimeLocalBRTparaUTC(ref2Input.value) : new Date();\n\n        document.getElementById(\"th-nivel1\").textContent = \"NÍVEL \" + formataHoraBR(alvo1).toUpperCase() + \"/\" + formataDataBR(alvo1);\n        document.getElementById(\"th-nivel2\").textContent = \"NÍVEL \" + formataHoraBR(alvo2).toUpperCase() + \"/\" + formataDataBR(alvo2);\n\n        // \"Atualizado em\" da chuva segue a mesma referência (boletim atual) usada no resto do boletim\n        atualizarChuvaUGRHI11(alvo2);\n        atualizarPrevisaoUGRHI11(alvo2);\n\n        const todosResultados = calcularResultados(medicoes, parametros, alvo1, alvo2);\n        const resultadosBarramentos = calcularResultadosBarramentos(medicoesBarr, medicoesJusante, alvo1, alvo2);\n\n        const resultadosCriticos = popularPontosCriticos(todosResultados);\n        popularPropagacao(todosResultados);\n        popularStatusGeral(todosResultados);\n        popularBarramentos(resultadosBarramentos);\n        ESTADO_ATUAL = { resultados: todosResultados, alvo1, alvo2 };\n        gerarDiagnosticoESintese(todosResultados, alvo1, alvo2, medicoesLongas);\n\n        const agoraBRT = paraBRT(alvo2);\n        const dataStr = String(agoraBRT.getUTCDate()).padStart(2, \"0\") + \"/\" + String(agoraBRT.getUTCMonth() + 1).padStart(2, \"0\") + \"/\" + agoraBRT.getUTCFullYear();\n        const horaStr = String(agoraBRT.getUTCHours()).padStart(2, \"0\") + \":\" + String(agoraBRT.getUTCMinutes()).padStart(2, \"0\");\n        document.getElementById(\"dataHoraGeral\").textContent = dataStr + \" - \" + horaStr;\n        document.getElementById(\"dataHoraPontos\").textContent = dataStr + \" - \" + horaStr;\n\n        mensagem(\"Dados atualizados via API SIBH-SPÁGUAS em \" + horaStr + \". Campos continuam editáveis para correção manual.\", \"#198754\");\n\n    } catch (erro) {\n        console.error(erro);\n        mensagem(\"Falha ao consultar a API do SIBH (\" + erro.message + \"). Preencha os campos manualmente.\", \"#b00020\");\n    }\n}\n\n// Se a leitura mais próxima do horário-alvo estiver mais distante do que isso, a estação é\n// tratada como \"sem dado\" naquele horário — evita contar um posto como monitorado usando\n// uma leitura velha (estação com transmissão parada) só porque ela existe dentro da janela de busca.\nconst LIMITE_DEFASAGEM_MS = 12 * 3600 * 1000; // 12 horas\n\nfunction leituraDentroDoLimite(leitura, alvoUTC) {\n    if (!leitura) return null;\n    return (Math.abs(new Date(leitura.date) - alvoUTC) <= LIMITE_DEFASAGEM_MS) ? leitura : null;\n}\n\nfunction calcularResultados(medicoes, parametros, alvo1, alvo2) {\n    return ESTACOES_RIBEIRA.map(p => {\n        const leitura1 = leituraDentroDoLimite(extrairLeituras(medicoes, p.id, alvo1).alvo, alvo1);\n        const leitura2 = leituraDentroDoLimite(extrairLeituras(medicoes, p.id, alvo2).alvo, alvo2);\n        const nivel07 = leitura1 ? leitura1.value / 100 : null;\n        const nivelAtual = leitura2 ? leitura2.value / 100 : null;\n        const variacao = (nivel07 !== null && nivelAtual !== null) ? nivelAtual - nivel07 : null;\n        const par = parametros[p.id] || null;\n        const status = classificarStatus(nivelAtual, par);\n        const cota = par ? par.extravasamento : null;\n        const acima = (nivelAtual !== null && cota !== null) ? nivelAtual - cota : null;\n\n        return { id: p.id, prefix: p.prefix, nome: p.nome, curto: p.curto, trecho: p.trecho, ordemRio: p.ordemRio, cota, par, nivel07, nivelAtual, variacao, acima, status };\n    });\n}\n\n// Lista TODOS os 8 pontos (como no modelo do PDF) — \"ACIMA DA COTA\" só é preenchido\n// quando a estação está de fato em extravasamento; nos demais casos fica \"—\".\n// Ordenados por \"acima da cota\" crescente; pontos sem excedência (sem valor) ficam por último.\nfunction popularPontosCriticos(todosResultados) {\n    const corpo = document.getElementById(\"corpoPontosCriticos\");\n    corpo.innerHTML = \"\";\n\n    // ordena seguindo o curso do rio, de montante para jusante (ver ordemRio em ESTACOES_RIBEIRA)\n    const ordenados = [...todosResultados].sort((a, b) => (a.ordemRio || 0) - (b.ordemRio || 0));\n\n    ordenados.forEach(r => {\n        const emExtravasamento = r.status === \"EXTRAVASAMENTO\" && r.acima !== null && !isNaN(r.acima);\n        const tr = document.createElement(\"tr\");\n        tr.innerHTML =\n            \"<td contenteditable=\\\"true\\\">\" + r.nome + \"</td>\" +\n            \"<td contenteditable=\\\"true\\\">\" + fmt(r.nivel07) + \" m</td>\" +\n            \"<td contenteditable=\\\"true\\\">\" + fmt(r.nivelAtual) + \" m</td>\" +\n            \"<td contenteditable=\\\"true\\\" class=\\\"\" + classeTendencia(r.variacao) + \"\\\">\" + fmtSinal(r.variacao) + \" m</td>\" +\n            \"<td class=\\\"\" + (emExtravasamento ? \"acima\" : \"\") + \"\\\" contenteditable=\\\"true\\\">\" + (emExtravasamento ? fmtSinal(r.acima) + \" m\" : \"—\") + \"</td>\" +\n            \"<td class=\\\"trend\\\">\" + gerarSelectTendencia(r) + \"</td>\";\n        corpo.appendChild(tr);\n    });\n\n    return todosResultados.filter(r =>\n        r.status === \"EXTRAVASAMENTO\" &&\n        r.nivel07 !== null && !isNaN(r.nivel07) &&\n        r.nivelAtual !== null && !isNaN(r.nivelAtual) &&\n        r.acima !== null && !isNaN(r.acima)\n    );\n}\n\n// Monta o <select> editável da coluna TENDÊNCIA, pré-selecionado conforme a tendência\n// calculada (ou a escolha manual anterior, se já tiver sido alterada).\nfunction gerarSelectTendencia(r) {\n    const atual = tendenciaEfetiva(r);\n    const opcoes = [\n        { valor: \"subida\", texto: \"↑ Subida\" },\n        { valor: \"estavel\", texto: \"→ Estável\" },\n        { valor: \"descida\", texto: \"↓ Queda\" },\n    ];\n    const optsHtml = opcoes.map(o =>\n        \"<option value=\\\"\" + o.valor + \"\\\"\" + (o.valor === atual ? \" selected\" : \"\") + \">\" + o.texto + \"</option>\"\n    ).join(\"\");\n    return \"<select class=\\\"tendencia-select \" + classeTendenciaEfetiva(r) + \"\\\" data-id=\\\"\" + r.id +\n        \"\\\" onchange=\\\"alterarTendenciaManual(this)\\\">\" + optsHtml + \"</select>\";\n}\n\n// Propagação da cheia: mostra dinamicamente só as estações do eixo principal que\n// estão em EXTRAVASAMENTO agora (igual ao modelo do PDF — número de colunas varia).\nfunction popularPropagacao(todosResultados) {\n    const headerRow = document.getElementById(\"propHeaderRow\");\n    const statusRow = document.getElementById(\"propStatusRow\");\n    if (!headerRow || !statusRow) return;\n    headerRow.innerHTML = \"\";\n    statusRow.innerHTML = \"\";\n\n    const rotulos = {\n        29794: \"Ribeira – Divisa Estadual\", 33203: \"Iporanga\", 29791: \"Eldorado\",\n        29726: \"Sete Barras\", 26243: \"Registro\", 1176: \"Pariquera-Açu\",\n    };\n\n    const emExtravasamento = Object.entries(PROPAGACAO_IDS)\n        .map(([elId, id]) => todosResultados.find(r => r.id === id))\n        .filter(r => r && r.status === \"EXTRAVASAMENTO\");\n\n    if (emExtravasamento.length === 0) {\n        headerRow.innerHTML = \"<th contenteditable=\\\"true\\\">Nenhum ponto do eixo principal em extravasamento</th>\";\n        statusRow.innerHTML = \"<td class=\\\"status-editavel\\\" contenteditable=\\\"true\\\" style=\\\"background:#4caf50;color:#fff;\\\">NORMAL</td>\";\n        return;\n    }\n\n    emExtravasamento.forEach(r => {\n        const th = document.createElement(\"th\");\n        th.contentEditable = \"true\";\n        th.textContent = rotulos[r.id] || r.curto;\n        headerRow.appendChild(th);\n\n        const td = document.createElement(\"td\");\n        td.className = \"status-editavel\";\n        td.contentEditable = \"true\";\n        td.textContent = \"EXTRAVASAMENTO\";\n        td.style.background = \"#f44336\";\n        td.style.color = \"#fff\";\n        statusRow.appendChild(td);\n    });\n}\n\nfunction popularStatusGeral(todosResultados) {\n    let normal = 0, atencao = 0, alerta = 0, emergencia = 0, extrav = 0;\n    const comDado = todosResultados.filter(r => r.nivelAtual !== null && !isNaN(r.nivelAtual));\n\n    comDado.forEach(r => {\n        if (r.status === \"EXTRAVASAMENTO\") extrav++;\n        else if (r.status === \"EMERGÊNCIA\") emergencia++;\n        else if (r.status === \"ALERTA\") alerta++;\n        else if (r.status === \"ATENÇÃO\") atencao++;\n        else normal++;\n    });\n\n    document.getElementById(\"card-total\").textContent = comDado.length;\n    document.getElementById(\"card-normal\").textContent = normal;\n    document.getElementById(\"card-atencao\").textContent = atencao;\n    document.getElementById(\"card-alerta\").textContent = alerta;\n    document.getElementById(\"card-emergencia\").textContent = emergencia;\n    document.getElementById(\"card-extrav\").textContent = extrav;\n}\n\n// Barramentos/reservatórios das cabeceiras — mesma lógica de leitura da tabela principal,\n// mas sem parâmetros de cota (a API pública ainda não publica extravasamento/alerta para estes pontos).\nfunction calcularResultadosBarramentos(medicoes, medicoesJusante, alvo1, alvo2) {\n    return ESTACOES_BARRAMENTOS.map(p => {\n        const leitura1 = leituraDentroDoLimite(extrairLeituras(medicoes, p.id, alvo1).alvo, alvo1);\n        const leitura2 = leituraDentroDoLimite(extrairLeituras(medicoes, p.id, alvo2).alvo, alvo2);\n        const nivelAnterior = leitura1 ? leitura1.value / 100 : null;\n        const nivelAtual = leitura2 ? leitura2.value / 100 : null;\n        const variacao = (nivelAnterior !== null && nivelAtual !== null) ? nivelAtual - nivelAnterior : null;\n\n        // Vazão defluente (m³/s) do posto de jusante correspondente — campo \"read_value\" da API,\n        // já em m³/s (sem dividir por 100, ao contrário de \"value\").\n        let jusante = null;\n        if (p.jusanteId !== null) {\n            const leituraJusante = leituraDentroDoLimite(extrairLeituras(medicoesJusante, p.jusanteId, alvo2).alvo, alvo2);\n            jusante = (leituraJusante && leituraJusante.read_value !== null && leituraJusante.read_value !== undefined)\n                ? leituraJusante.read_value : null;\n        }\n\n        return { id: p.id, prefix: p.prefix, nome: p.nome, nivelAnterior, nivelAtual, variacao, jusante };\n    });\n}\n\nfunction popularBarramentos(resultados) {\n    const corpo = document.getElementById(\"corpoBarramentos\");\n    if (!corpo) return;\n    corpo.innerHTML = \"\";\n    resultados.forEach(r => {\n        const tr = document.createElement(\"tr\");\n        tr.innerHTML =\n            \"<td contenteditable=\\\"true\\\">\" + r.nome + \"</td>\" +\n            \"<td contenteditable=\\\"true\\\">\" + fmt(r.nivelAnterior) + \" m</td>\" +\n            \"<td contenteditable=\\\"true\\\">\" + fmt(r.nivelAtual) + \" m</td>\" +\n            \"<td class=\\\"\" + (r.jusante !== null ? \"cota-auto\" : \"cota-manual\") + \"\\\" contenteditable=\\\"true\\\">\" +\n                (r.jusante !== null ? fmt(r.jusante) + \" m³/s\" : \"—\") + \"</td>\" +\n            \"<td contenteditable=\\\"true\\\" class=\\\"\" + classeTendencia(r.variacao) + \"\\\">\" + fmtSinal(r.variacao) + \" m</td>\" +\n            \"<td class=\\\"trend\\\" contenteditable=\\\"true\\\">\" + tendenciaTexto(r.variacao) + \"</td>\";\n        corpo.appendChild(tr);\n    });\n    prepararSelecaoLinhas(\"tabelaBarramentos\");\n    prepararSelecaoColunas(\"tabelaBarramentos\");\n}\n\n// Situação geral (montante x jusante) — resumo automático de 1 frase, no mesmo\n// espírito do \"DIAGNÓSTICO EXECUTIVO\" do modelo em PDF.\nfunction gerarDiagnosticoESintese(todosResultados, alvo1, alvo2, medicoesLongas) {\n    const horaTxt = formataReferenciaTxt(alvo2, alvo1);\n    const comDado = todosResultados.filter(r => r.nivelAtual !== null && !isNaN(r.nivelAtual) && r.variacao !== null);\n    const emExtrav = todosResultados.filter(r => r.status === \"EXTRAVASAMENTO\" && r.acima !== null);\n\n    if (comDado.length === 0) {\n        document.getElementById(\"diagnosticoTexto\").textContent = \"Sem dados suficientes para diagnóstico no momento.\";\n        document.getElementById(\"sinteseTexto\").innerHTML = \"<p>Sem dados suficientes para síntese no momento.</p>\";\n        return;\n    }\n\n    const subindo = comDado.filter(r => tendenciaEfetiva(r) === \"subida\");\n    const descendo = comDado.filter(r => tendenciaEfetiva(r) === \"descida\");\n\n    let diagTxt;\n    if (emExtrav.length === 0) {\n        diagTxt = \"Nenhum dos \" + todosResultados.length + \" pontos monitorados no Vale do Ribeira de Iguape está acima da cota de extravasamento às \" + horaTxt + \".\";\n    } else {\n        const maiorExcedencia = emExtrav.reduce((a, b) => (b.acima > a.acima ? b : a));\n        diagTxt = \"Às \" + horaTxt + \", \" + emExtrav.length + \" de \" + todosResultados.length +\n            \" pontos monitorados permanecem em extravasamento no Vale do Ribeira de Iguape\" +\n            (descendo.length ? \", com redução de nível em \" + descendo.length + \" deles (em geral nos pontos mais a montante)\" : \"\") +\n            (subindo.length ? (descendo.length ? \" e\" : \",\") + \" elevação em \" + subindo.length + \" ponto(s)\" : \"\") +\n            \". Maior excedência em \" + maiorExcedencia.curto + \" (\" + fmtSinal(maiorExcedencia.acima) + \" m acima da cota).\";\n    }\n    document.getElementById(\"diagnosticoTexto\").textContent = diagTxt;\n\n    const qtdNormal = comDado.filter(r => r.status === \"NORMAL\").length;\n    let html = \"<p>Das \" + todosResultados.length + \" estações monitoradas, \" + emExtrav.length + \" permanece\" + (emExtrav.length === 1 ? \"\" : \"m\") +\n        \" em extravasamento\" +\n        (comDado.filter(r => r.status === \"ALERTA\").length ? \", \" + comDado.filter(r => r.status === \"ALERTA\").length + \" em alerta\" : \"\") +\n        (comDado.filter(r => r.status === \"EMERGÊNCIA\").length ? \", \" + comDado.filter(r => r.status === \"EMERGÊNCIA\").length + \" em emergência\" : \"\") +\n        (comDado.filter(r => r.status === \"ATENÇÃO\").length ? \" e \" + comDado.filter(r => r.status === \"ATENÇÃO\").length + \" em atenção\" : \"\") +\n        \". \" + qtdNormal + \" estação(ões) apresenta(m) condição de normalidade.</p>\";\n\n    const mesmoDiaDeHoje = formataDataBR(alvo2) === formataDataBR(new Date());\n    const horaAtualTxt = formataHoraMinBR(alvo2) + (mesmoDiaDeHoje ? \" de hoje\" : \" de \" + formataDataBR(alvo2));\n\n    todosResultados.forEach(r => {\n        const nomeFormatado = r.nome.replace(/\\s*\\(([^)]+)\\)\\s*$/, \", $1\");\n        const nomeRealce = \"<strong style=\\\"background:#d7dce0;color:\" + corTextoStatus(r.status) + \";padding:1px 5px;border-radius:3px;\\\">\" + nomeFormatado + \":</strong>\";\n        if (r.nivelAtual === null || isNaN(r.nivelAtual)) {\n            html += \"<p>\" + nomeRealce + \" sem leitura disponível na API no momento.</p>\";\n            return;\n        }\n        const efetivo = tendenciaEfetiva(r);\n        const tendFinalTxt = efetivo === \"subida\" ? \"subida\" : (efetivo === \"descida\" ? \"queda\" : (efetivo === \"estavel\" ? \"estável\" : \"—\"));\n        const statusTxt = r.status === \"NORMAL\" ? \"normalidade\" : r.status.toLowerCase();\n        const fechamentoTxt = \"O monitoramento dos dados mais recentes indica que o nível permanece em <strong>\" + tendFinalTxt + \"</strong>.\";\n        const variacaoTxt = (r.variacao !== null && !isNaN(r.variacao))\n            ? (\"com variação de <strong>\" + fmtSinal(r.variacao) + \" m</strong> no período em análise\")\n            : \"sem variação registrada no período em análise\";\n\n        let corpo;\n        if (r.status === \"EXTRAVASAMENTO\") {\n            // Modelo \"EXTRAVASAMENTO\"\n            const inicioStatus = medicoesLongas ? encontrarInicioStatus(medicoesLongas, r.id, r.par, r.status, alvo2) : null;\n            const desdeTxt = inicioStatus === \"LIMITE\" ? \" desde <strong>[PREENCHER]</strong>, às <strong>[PREENCHER]</strong>\"\n                : inicioStatus ? (\" desde \" + formataDataBR(inicioStatus) + \", às \" + formataHoraMinBR(inicioStatus)) : \"\";\n            const cotaTxt = (r.cota !== null)\n                ? (\", aproximadamente <strong>\" + fmt(Math.abs(r.acima)) + \" m acima</strong> da cota de extravasamento de \" + fmt(r.cota) + \" m\")\n                : \"\";\n            corpo = \"permanece em extravasamento\" + desdeTxt + \". Às \" + horaAtualTxt + \", o posto registrava nível de \" +\n                fmt(r.nivelAtual) + \" m\" + cotaTxt + \", \" + variacaoTxt + \". \" + fechamentoTxt;\n        } else {\n            // Se NÃO está em extravasamento agora mas esteve nas últimas 24h, usa o modelo \"QUANDO SAIR DO EXTRAVASAMENTO\"\n            const saidaExtrav = medicoesLongas ? encontrarSaidaExtravasamento(medicoesLongas, r.id, r.par, r.status, alvo2) : null;\n            if (saidaExtrav) {\n                corpo = \"Saiu de extravasamento às \" + formataHoraMinBR(saidaExtrav) + \" de \" + formataDataBR(saidaExtrav) +\n                    \". Às \" + horaAtualTxt + \", o posto registrava nível de \" + fmt(r.nivelAtual) + \" m, \" + variacaoTxt + \". \" + fechamentoTxt;\n            } else {\n                // Modelo \"NÃO EXTRAVASAMENTO\"\n                corpo = \"permanece em \" + statusTxt + \". Às \" + horaAtualTxt + \", o posto registrava nível de \" +\n                    fmt(r.nivelAtual) + \" m, \" + variacaoTxt + \". \" + fechamentoTxt;\n            }\n        }\n\n        html += \"<p>\" + nomeRealce + \" \" + corpo + \"</p>\";\n    });\n\n    document.getElementById(\"sinteseTexto\").innerHTML = html;\n}\n\n/* =========================================================\n   SELEÇÃO / ADIÇÃO / EXCLUSÃO DE LINHAS E COLUNAS (tabelas manuais)\n========================================================= */\n\nfunction prepararSelecaoLinhas(tabelaId) {\n    const tabela = document.getElementById(tabelaId);\n    if (!tabela) return;\n    tabela.querySelectorAll(\"tbody tr\").forEach(tr => {\n        tr.onclick = function (e) {\n            if (e.target.tagName.toLowerCase() === \"button\") return;\n            tabela.querySelectorAll(\"tbody tr\").forEach(r => r.classList.remove(\"linha-selecionada\"));\n            this.classList.add(\"linha-selecionada\");\n        };\n    });\n}\n\nfunction adicionarLinha(tabelaId, colunas) {\n    const tabela = document.getElementById(tabelaId);\n    if (!tabela) return;\n    const tbody = tabela.querySelector(\"tbody\");\n    const nColunas = colunas || tabela.querySelectorAll(\"thead th\").length;\n    const tr = document.createElement(\"tr\");\n    for (let i = 0; i < nColunas; i++) {\n        const td = document.createElement(\"td\");\n        td.setAttribute(\"contenteditable\", \"true\");\n        td.textContent = \"—\";\n        tr.appendChild(td);\n    }\n    tbody.appendChild(tr);\n    prepararSelecaoLinhas(tabelaId);\n    tr.scrollIntoView({ behavior: \"smooth\", block: \"center\" });\n    mensagem(\"Nova linha adicionada. Clique nos campos para editar.\", \"#198754\");\n}\n\nfunction excluirLinhaSelecionada(tabelaId) {\n    const tabela = document.getElementById(tabelaId);\n    if (!tabela) return;\n    const selecionada = tabela.querySelector(\"tbody tr.linha-selecionada\");\n    if (!selecionada) { mensagem(\"Selecione uma linha da tabela antes de excluir.\", \"#b26a00\"); return; }\n    if (!confirm(\"Deseja excluir a linha selecionada?\")) return;\n    selecionada.remove();\n    mensagem(\"Linha excluída.\", \"#dc3545\");\n}\n\nfunction prepararSelecaoColunas(tabelaId) {\n    const tabela = document.getElementById(tabelaId);\n    if (!tabela) return;\n    tabela.querySelectorAll(\"thead th\").forEach((th, i) => {\n        th.onclick = function () {\n            tabela.querySelectorAll(\"thead th\").forEach(h => h.classList.remove(\"coluna-selecionada\"));\n            th.classList.add(\"coluna-selecionada\");\n            tabela.dataset.colunaSelecionada = i;\n        };\n    });\n}\n\nfunction adicionarColuna(tabelaId) {\n    const tabela = document.getElementById(tabelaId);\n    if (!tabela) return;\n    const headerRow = tabela.querySelector(\"thead tr\");\n    const th = document.createElement(\"th\");\n    th.setAttribute(\"contenteditable\", \"true\");\n    th.textContent = \"Nova coluna\";\n    headerRow.appendChild(th);\n    tabela.querySelectorAll(\"tbody tr\").forEach(tr => {\n        const td = document.createElement(\"td\");\n        td.setAttribute(\"contenteditable\", \"true\");\n        td.textContent = \"—\";\n        tr.appendChild(td);\n    });\n    prepararSelecaoColunas(tabelaId);\n    mensagem(\"Nova coluna adicionada. Clique no título para renomear.\", \"#198754\");\n}\n\nfunction excluirColunaSelecionada(tabelaId) {\n    const tabela = document.getElementById(tabelaId);\n    if (!tabela) return;\n    const idx = tabela.dataset.colunaSelecionada;\n    if (idx === undefined) { mensagem(\"Clique no título de uma coluna antes de excluir.\", \"#b26a00\"); return; }\n    if (!confirm(\"Deseja excluir a coluna selecionada?\")) return;\n    const i = Number(idx);\n    tabela.querySelectorAll(\"thead tr\").forEach(tr => { if (tr.children[i]) tr.children[i].remove(); });\n    tabela.querySelectorAll(\"tbody tr\").forEach(tr => { if (tr.children[i]) tr.children[i].remove(); });\n    delete tabela.dataset.colunaSelecionada;\n    tabela.querySelectorAll(\"thead th\").forEach(h => h.classList.remove(\"coluna-selecionada\"));\n    mensagem(\"Coluna excluída.\", \"#dc3545\");\n}\n\n/* =========================================================\n   SALVAR / CARREGAR / EXPORTAR\n========================================================= */\n\nconst CHAVE = \"sumarioExecutivoRibeiraIguapeEditavel\";\n\nfunction obterConteudo() {\n    return {\n        pagina1: document.getElementById(\"pagina1\").innerHTML,\n        pagina2: document.getElementById(\"pagina2\").innerHTML,\n        pagina4: document.getElementById(\"pagina4\").innerHTML,\n    };\n}\n\nfunction salvarDados() {\n    localStorage.setItem(CHAVE, JSON.stringify(obterConteudo()));\n    localStorage.setItem(CHAVE + \"_data\", new Date().toLocaleString(\"pt-BR\"));\n    mensagem(\"Alterações salvas com sucesso.\", \"#198754\");\n}\n\nfunction carregarDados() {\n    const salvo = localStorage.getItem(CHAVE);\n    if (!salvo) { mensagem(\"Nenhuma versão salva encontrada.\", \"#b26a00\"); return; }\n    try {\n        const dados = JSON.parse(salvo);\n        if (dados.pagina1) document.getElementById(\"pagina1\").innerHTML = dados.pagina1;\n        if (dados.pagina2) document.getElementById(\"pagina2\").innerHTML = dados.pagina2;\n        if (dados.pagina4) document.getElementById(\"pagina4\").innerHTML = dados.pagina4;\n        mensagem(\"Versão salva carregada.\", \"#0b5d89\");\n    } catch (e) {\n        mensagem(\"Não foi possível carregar a versão salva.\", \"#b00020\");\n    }\n}\n\nfunction restaurarPadrao() {\n    if (!confirm(\"Deseja apagar as alterações salvas e restaurar o modelo original?\")) return;\n    localStorage.removeItem(CHAVE);\n    localStorage.removeItem(CHAVE + \"_data\");\n    location.reload();\n}\n\nfunction baixarHTML() {\n    salvarDados();\n    const clone = document.documentElement.cloneNode(true);\n    [\"pagina1\", \"pagina2\", \"pagina4\"].forEach(id => {\n        clone.querySelector(\"#\" + id).innerHTML = document.getElementById(id).innerHTML;\n    });\n    const status = clone.querySelector(\"#statusMsg\");\n    if (status) status.textContent = \"Clique em qualquer campo para editar.\";\n\n    const conteudo = \"<!DOCTYPE html>\\n\" + clone.outerHTML;\n    const blob = new Blob([conteudo], { type: \"text/html;charset=utf-8\" });\n    const url = URL.createObjectURL(blob);\n    const link = document.createElement(\"a\");\n    link.href = url;\n    const data = new Date().toISOString().slice(0, 10).replaceAll(\"-\", \"\");\n    link.download = \"sumario_executivo_ribeira_iguape_\" + data + \".html\";\n    document.body.appendChild(link);\n    link.click();\n    link.remove();\n    URL.revokeObjectURL(url);\n    mensagem(\"HTML atualizado baixado.\", \"#7b2cbf\");\n}\n\nwindow.addEventListener(\"DOMContentLoaded\", function () {\n    const salvo = localStorage.getItem(CHAVE);\n    if (salvo) {\n        try {\n            const dados = JSON.parse(salvo);\n            if (dados.pagina1) document.getElementById(\"pagina1\").innerHTML = dados.pagina1;\n            if (dados.pagina2) document.getElementById(\"pagina2\").innerHTML = dados.pagina2;\n            if (dados.pagina4) document.getElementById(\"pagina4\").innerHTML = dados.pagina4;\n        } catch (e) {}\n    }\n    atualizarDadosAPI();\n});\n\n</script>\n\n</body>\n</html>\n";
